  user_input_enabled?: boolean;
  computational?: ComputationalObject | ComputationalProcess;
  stateful?: boolean; // ISO 19450 §3.66/§3.67. undefined ≡ true (backwards-compatible)
}

export interface State {
  id: string;
  parent: string;
  name: string;
  initial: boolean;
  final: boolean;
  default: boolean;
  current?: boolean;
  duration?: Duration;
  hyperlinks?: string[];
}

export interface OPD {
  id: string;
  name: string;
  opd_type: OpdType;
  parent_opd: string | null;
  refines?: string;
  refinement_type?: RefinementType;
}

export interface Link {
  id: string;
  type: LinkType;
  source: string;
  target: string;
  source_state?: string;
  target_state?: string;
  multiplicity_source?: string;
  multiplicity_target?: string;
  probability?: number;
  rate?: Rate;
  path_label?: string;
  tag?: string;
  direction?: Direction;
  tag_reverse?: string;
  ordered?: boolean;
  invocation_interval?: Duration;
  discriminating?: boolean;
