export function validateOpl(text: string, options: { modelName?: string } = {}): ValidationResult {
  const syntax = parseOplWithAbsoluteSpans(text);
  if (!syntax.ok) {
    return {
      ok: false,
      issues: syntax.error.issues.map((issue) => ({
        phase: "V1-syntax",
        severity: "error",
        message: issue.message,
        line: issue.line,
