 70	      ok: false,
 71	      issues: syntax.error.issues.map((issue) => ({
 72	        phase: "V1-syntax",
 73	        severity: "error",
 74	        message: issue.message,
 75	        line: issue.line,
 76	        column: issue.column,
 77	        endLine: issue.line,
 78	        endColumn: issue.column + issue.text.length,
 79	      })),
 80	      phases: {
 81	        syntax: "fail",
 82	        binding: "skip",
 83	        semantic: "skip",
 84	        canonical: "skip",
 85	      },
 86	    };
 87	  }
