130	function parseOplWithAbsoluteSpans(text: string) {
131	  const sections = splitSections(text);
132	  if (!sections) {
133	    const parsed = parseOplDocument(text, "SD", "opd-sd");
134	    if (!parsed.ok) return parsed;
135	    return { ok: true as const, value: [parsed.value] };
136	  }
137	
138	  const docs: OplDocument[] = [];
139	  for (const section of sections) {
140	    const parsed = parseOplDocument(section.text, section.name, `opd-${slug(section.name) || "section"}`);
141	    if (!parsed.ok) {
142	      return {
143	        ok: false as const,
144	        error: {
145	          ...parsed.error,
146	          issues: parsed.error.issues.map((issue) => ({
147	            ...issue,
148	            line: issue.line + section.startLine - 1,
149	          })),
150	        },
151	      };
152	    }
153	    docs.push(adjustDocumentSpans(parsed.value, section.startLine - 1, section.startOffset));
154	  }
155	  return { ok: true as const, value: docs };
156	}
