158	function splitSections(text: string): ParsedSection[] | null {
159	  const lines = text.split("\n");
160	  const entries = [] as Array<{ text: string; lineNumber: number; offset: number }>;
161	  let offset = 0;
162	  for (let i = 0; i < lines.length; i++) {
163	    entries.push({ text: lines[i]!, lineNumber: i + 1, offset });
164	    offset += lines[i]!.length + 1;
165	  }
166	
167	  const sections: ParsedSection[] = [];
168	  let current: ParsedSection | null = null;
169	  for (const entry of entries) {
170	    const match = entry.text.trim().match(/^=== (.*?) ===$/);
171	    if (match) {
172	      current = {
173	        name: match[1]!.trim(),
174	        startLine: entry.lineNumber + 1,
175	        startOffset: entry.offset + entry.text.length + 1,
176	        text: "",
177	      };
178	      sections.push(current);
179	      continue;
180	    }
181	    if (!current) {
182	      if (entry.text.trim()) return null;
183	      continue;
184	    }
185	    current.text += current.text ? `\n${entry.text}` : entry.text;
186	  }
187	
188	  return sections.length > 0 ? sections : null;
189	}
